// the story's footnotes in text order: story.footnotes is not always in that order (after placing into a
// threaded template it may start mid-text and wrap round; 02.10.2026)
function notesInOrder(story) {
  var a = [], i, f = story.footnotes;
  for (i = 0; i < f.length; i++) { a.push(f[i]); }
  a.sort(function (x, y) { return x.storyOffset.index - y.storyOffset.index; });
  return a;
}


// After the report the script offers to make the changes itself (MB, 02.10.2026): one undo step (Edit > Undo).
// SROM_APPLY = true / false set before running skips the question (tests).
function wantApply(n, what) {
  if (n === 0) { return false; }
  if (typeof SROM_APPLY !== "undefined") { return SROM_APPLY === true; }
  return confirm("SROM: " + what + " (" + n + ")?\rOne undo step: Edit > Undo reverses all of it.");
}

// replace the note's text from "Ibidem" to its end by FULL; *…* become the italic character style
function retype(doc, fn, full) {
  var c = fn.characters, txt = String(fn.texts[0].contents), i0 = txt.search(/[Ii]bidem/), plain = "", spans = [], i, on = -1;
  if (i0 < 0) { return false; }
  for (i = 0; i < full.length; i++) {
    if (full.charAt(i) === "*") { if (on < 0) { on = plain.length; } else { spans.push([on, plain.length]); on = -1; } }
    else { plain += full.charAt(i); }
  }
  c.itemByRange(i0, c.length - 1).contents = plain;
  var none = doc.characterStyles[0], it = doc.characterStyles.itemByName(ITALIC);
  c = fn.characters;
  c.itemByRange(i0, c.length - 1).applyCharacterStyle(none);
  for (i = 0; i < spans.length; i++) { if (spans[i][1] > spans[i][0]) { c.itemByRange(i0 + spans[i][0], i0 + spans[i][1] - 1).applyCharacterStyle(it); } }
  return true;
}

function pad(n) { return (n < 10 ? "  " : (n < 100 ? " " : "")) + n; }

function mainStory(doc) {
  var best = null, i;
  for (i = 0; i < doc.stories.length; i++) {
    if (best === null || doc.stories[i].footnotes.length > best.footnotes.length) { best = doc.stories[i]; }
  }
  return best;
}

// where does the start of this footnote sit? {ok, page, frame, col}
function locate(fn) {
  var ip, frames, fr, pg, col = 0, b, ins, n, gut, w, x;
  try {
    ip = fn.texts[0].insertionPoints[0];
    frames = ip.parentTextFrames;
    if (!frames || frames.length === 0) { return {ok: false, why: "overset / not laid out"}; }
    fr = frames[0];
    pg = fr.parentPage ? fr.parentPage.name : "?";
    n = fr.textFramePreferences.textColumnCount;
    if (n > 1) {
      b = fr.geometricBounds; // [y1, x1, y2, x2]
      ins = fr.textFramePreferences.insetSpacing;
      gut = fr.textFramePreferences.textColumnGutter;
      x = ip.horizontalOffset - b[1] - (ins instanceof Array ? ins[1] : ins);
      w = (b[3] - b[1] - (ins instanceof Array ? ins[1] + ins[3] : 2 * ins) - (n - 1) * gut) / n;
      col = Math.floor(x / (w + gut));
      if (col < 0) { col = 0; }
      if (col > n - 1) { col = n - 1; }
    }
    return {ok: true, page: pg, frame: fr.id, col: col};
  } catch (e) {
    return {ok: false, why: "error: " + e};
  }
}

function selectedStory() {
  // text cursor or text frame selected -> that story; nothing usable selected -> null
  try {
    if (app.selection.length) {
      var x = app.selection[0];
      var st = x.parentStory;
      if (st && st.isValid) { return st; }
    }
  } catch (e) {}
  return null;
}

function main() {
  if (app.documents.length === 0) { alert("SROM Ibidem check: no document open."); return; }
  var doc = app.activeDocument;
  // one article in a larger document: put the cursor in its text first
  var story = selectedStory() || mainStory(doc);
  var fns = story ? notesInOrder(story) : [];
  var out = [], todo = [], fix = [], checked = 0, k, n, cur, prv, a, b, txt, i;
  out.push("SROM Ibidem check — " + doc.name);
  out.push("footnotes in main story: " + fns.length + " / expected from build: " + EXPECTED_TOTAL);
  if (fns.length !== EXPECTED_TOTAL) {
    out.push("!! COUNT MISMATCH — numbering below is unreliable; fix the import first.");
    todo.push("footnote count differs from the build: run the post-import check first");
  }
  for (k in MAP) {
    if (!MAP.hasOwnProperty(k)) { continue; }
    n = parseInt(k, 10);
    if (n < 2 || n > fns.length) { out.push(pad(n) + "  !! note not found"); todo.push("note " + n + ": not found"); continue; }
    cur = fns[n - 1]; prv = fns[n - 2];
    txt = cur.texts[0].contents;
    if (String(txt).search(/[Ii]bidem/) < 0 && String(txt).indexOf(MAP[k].full.replace(/\*/g, "").substr(0, 40)) >= 0) {
      out.push(pad(n) + "  ok (retyped in full)"); continue;
    }
    if (String(txt).search(/[Ii]bidem/) < 0) {
      out.push(pad(n) + "  !! expected Ibidem, found: " + String(txt).substr(0, 60)); todo.push("note " + n + ": the build wrote Ibidem here, the document has other text — check the note by eye"); continue;
    }
    a = locate(prv); b = locate(cur); checked++;
    if (!a.ok || !b.ok) {
      out.push(pad(n) + "  ?? cannot locate (" + (a.ok ? b.why : a.why) + ") — check by eye"); todo.push("note " + n + ": cannot be located (" + (a.ok ? b.why : a.why) + "): check by eye once the text fits");
    } else if (a.page !== b.page || a.frame !== b.frame || a.col !== b.col) {
      out.push(pad(n) + "  REPLACE: “Ibidem” points to note " + (n - 1) + " on p. " + a.page + (a.col ? " col " + (a.col + 1) : "") + ", but this note is on p. " + b.page + (b.col ? " col " + (b.col + 1) : "") + " (Kanon § 7.3)");
      out.push("       type instead: " + MAP[k].full);
      todo.push("note " + n + " (p. " + b.page + "): replace its text with the one shown at note " + n + " above (*…* = Kursywa)");
      fix.push([cur, MAP[k].full, n]);
    } else {
      out.push(pad(n) + "  ok (p." + b.page + " col " + (b.col + 1) + ")");
    }
  }
  if (checked === 0) { out.push("no CSL Ibidem notes in this article."); }
  if (todo.length === 0) { out.push("RESULT: OK"); }
  else {
    out.push("");
    out.push("RESULT: " + todo.length + " item(s) need attention:");
    for (i = 0; i < todo.length; i++) { out.push("  " + (i + 1) + ". " + todo[i]); }
  }

  if (wantApply(fix.length, "retype the Ibidem notes listed (" + (function () { var r = [], j; for (j = 0; j < fix.length; j++) { r.push(fix[j][2]); } return r.join(", "); })() + ")")) {
    var done = [];
    app.doScript(function () { var j; for (j = 0; j < fix.length; j++) { if (retype(doc, fix[j][0], fix[j][1])) { done.push(fix[j][2]); } } },
                 ScriptLanguage.JAVASCRIPT, undefined, UndoModes.ENTIRE_SCRIPT, "SROM Ibidem");
    out.push("");
    out.push("APPLIED: notes " + done.join(", ") + " retyped (Edit > Undo reverses it). The layout may have moved: run this script again.");
  }
  var report = out.join("\r");
  var f;
  try { f = new File(doc.filePath + "/" + doc.name.replace(/\.indd$/i, "") + "_ibidem.txt"); }
  catch (e) { f = new File(Folder.desktop + "/srom_ibidem.txt"); }
  f.encoding = "UTF-8";
  if (f.open("w")) { f.write(report); f.close(); }
  if (report.length > 1800) {
    // the attention list stays visible: the middle of a long report is cut, not the end
    report = out.slice(0, 2).join("\r") + "\r…\r" + out.slice(out.length - todo.length - 2).join("\r") + "\r\rfull report: " + f.fsName;
  }
  alert(report);
}

main();
